files.billing.py:
def calc_tax(amount_cents, rate):
    return int(amount_cents * rate)


def total_with_tax(amount_cents, rate):
    return amount_cents + calc_tax(amount_cents, rate)


def format_total(amount_cents, rate):
    t = total_with_tax(amount_cents, rate)
    return "%d.%02d" % (t // 100, t % 100)

