from billing import calc_tax, format_total, total_with_tax


def test_exact_amounts():
    assert calc_tax(1000, 0.1) == 100
    assert total_with_tax(1000, 0.1) == 1100


def test_format_total():
    assert format_total(1000, 0.1) == "11.00"

